from builtins import object
from taf.ul.trs_e2e_fw.lib.attenuator.tool_base import ToolBase
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable


class ToolFactory(object):

    def __init__(self, device):
        self.device = device

    def get_tool_obj(self):
        return self._choose_generator_tool()

    def _choose_generator_tool(self):
        generator_tool = get_config_variable(['attenuator', self.device, 'tool'])
        for tool in ToolBase.__subclasses__():
            if tool.check_tool(generator_tool):
                return tool()
